// apps/server/src/http.ts
function sendError(req, reply, err) {
  const requestId = req.requestId ?? "unknown";
  if (err instanceof ZodError) {
    return reply.status(400).send(
      fail(
        requestId,
        "VALIDATION",
        "Some fields could not be read.",
        err.issues.map((i) => ({ path: i.path.join("."), message: i.message }))
      )
    );
  }
  if (err instanceof DomainError) {
    return reply.status(err.httpStatus).send(fail(requestId, err.code, err.message, err.details));
  }
  const status = err.httpStatus;
  if (status === 403) {
    return reply.status(403).send(fail(requestId, "FORBIDDEN", "You do not have permission to view this."));
  }
  req.log.error(err);
  return reply.status(500).send(
    fail(
      requestId,
      "INTERNAL",
      "Something went wrong. Quote this request id if you contact support."
    )
  );
}

