async function upgradeLegacyDemo(ctx, now) {
  await ctx.sqlite.prepare(
    `UPDATE department SET name = 'Production', code = 'PRD', updated_at = ? WHERE code = 'ENG'`
  ).run(now);
  await ctx.sqlite.prepare(`UPDATE team SET name = 'Printing', updated_at = ? WHERE name = 'Platform'`).run(now);
  await ctx.sqlite.prepare(
    `UPDATE team SET name = 'Binding & Finishing', updated_at = ? WHERE name = 'Customer Support'`
  ).run(now);
  await ctx.sqlite.prepare(
    `UPDATE department SET name = 'Administration', updated_at = ? WHERE code = 'GEN' AND name = 'General'`
  ).run(now);
  for (const [oldEmail, key] of Object.entries(LEGACY)) {
    const person = DEMO_PEOPLE.find((p) => p.key === key);
    const account = await ctx.sqlite.prepare(`SELECT id, employee_id AS "employeeId" FROM user_account WHERE email = ?`).get(oldEmail);
    if (!account) continue;
    const taken = await ctx.sqlite.prepare(`SELECT id FROM user_account WHERE email = ?`).get(demoEmail(key));
    if (taken) continue;
    await ctx.sqlite.prepare(`UPDATE user_account SET email = ?, updated_at = ? WHERE id = ?`).run(demoEmail(key), now, account.id);
    if (account.employeeId) {
      await ctx.sqlite.prepare(
        `UPDATE employee SET first_name = ?, last_name = ?, work_email = ?, employee_code = ?,
                    joined_on = ?, updated_at = ? WHERE id = ?`
      ).run(
        person.first,
        person.last,
        demoEmail(key),
        person.code,
        person.joined,
        now,
        account.employeeId
      );
    }
  }
  const admin = await ctx.sqlite.prepare(
    `SELECT id, employee_id AS "employeeId" FROM user_account WHERE email = 'admin@example.invalid'`
  ).get();
  if (admin && !await ctx.sqlite.prepare(`SELECT id FROM user_account WHERE email = ?`).get(DEMO_ADMIN.email)) {
    await ctx.sqlite.prepare(`UPDATE user_account SET email = ? WHERE id = ?`).run(DEMO_ADMIN.email, admin.id);
    if (admin.employeeId) {
      await ctx.sqlite.prepare(
        `UPDATE employee SET first_name = 'Arjun', last_name = 'Das', work_email = ? WHERE id = ?`
      ).run(DEMO_ADMIN.email, admin.employeeId);
    }
  }
}
async function adoptAnnualLeave(ctx, actorId) {
  const periodId = await currentPeriodId(ctx);
  const period = await ctx.sqlite.prepare(`SELECT starts_on AS "startsOn" FROM leave_period WHERE id = ?`).get(periodId);
  await withTx(ctx.sqlite, async () => {
    const existing = await ctx.sqlite.prepare(`SELECT id FROM leave_type WHERE code = 'AL'`).get();
    if (!existing) {
      const typeId = newId();
      const versionId = newId();
      await ctx.sqlite.prepare(
        `INSERT INTO leave_type (id, code, name, colour_token, is_paid, created_at, created_by, updated_at, updated_by)
           VALUES (?, 'AL', 'Annual Leave', 'accent', 1, ?, ?, ?, ?)`
      ).run(typeId, ctx.now, actorId, ctx.now, actorId);
      await ctx.sqlite.prepare(
        `INSERT INTO leave_policy_version (id, leave_type_id, version_no, effective_from, rules_json, published_at, published_by, created_at, created_by)
           VALUES (?, ?, 1, ?, ?, ?, ?, ?, ?)`
      ).run(
        versionId,
        typeId,
        period.startsOn,
        JSON.stringify(defaultRulesForCode("AL")),
        ctx.now,
        actorId,
        ctx.now,
        actorId
      );
      await ctx.sqlite.prepare(
        `INSERT INTO policy_assignment (id, leave_policy_version_id, scope_type, scope_id, priority) VALUES (?, ?, 'company', 'company', 0)`
      ).run(newId(), versionId);
    } else {
      await ctx.sqlite.prepare(`UPDATE leave_type SET archived_at = NULL WHERE id = ?`).run(existing.id);
    }
    await ctx.sqlite.prepare(
      `UPDATE leave_type SET archived_at = ?, updated_at = ? WHERE code != 'AL' AND archived_at IS NULL`
    ).run(ctx.now, ctx.now);
  });
}
