async function publishDemoEarnedLeavePolicy(ctx, actorId) {
  const el = await ctx.sqlite.prepare(`SELECT id FROM leave_type WHERE code = 'AL'`).get();
  if (!el) return;
  const latest = await ctx.sqlite.prepare(
    `SELECT version_no AS n, rules_json AS rules FROM leave_policy_version WHERE leave_type_id = ? ORDER BY version_no DESC LIMIT 1`
  ).get(el.id);
  if (latest && latest.rules.includes("confirmedUnderMonthlyHalfDays")) return;
  const rules = defaultRulesForCode("AL");
  const versionId = newId();
  const period = await ctx.sqlite.prepare(`SELECT starts_on AS "startsOn" FROM leave_period WHERE id = ?`).get(await currentPeriodId(ctx));
  await ctx.sqlite.prepare(
    `INSERT INTO leave_policy_version (id, leave_type_id, version_no, effective_from, rules_json, published_at, published_by, created_at, created_by)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`
  ).run(
    versionId,
    el.id,
    (latest?.n ?? 0) + 1,
    period.startsOn,
    JSON.stringify(rules),
    ctx.now,
    actorId,
    ctx.now,
    actorId
  );
  await ctx.sqlite.prepare(
    `INSERT INTO policy_assignment (id, leave_policy_version_id, scope_type, scope_id, priority) VALUES (?, ?, 'company', 'company', 0)`
  ).run(newId(), versionId);
}
function addDays2(iso, n) {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}
function monday(iso) {
  const dow = (/* @__PURE__ */ new Date(`${iso}T00:00:00Z`)).getUTCDay();
  return addDays2(iso, (8 - dow) % 7);
}
async function actingAs(ctx, key, today = ctx.today) {
  const user = await ctx.sqlite.prepare(`SELECT id FROM user_account WHERE email = ?`).get(demoEmail(key));
  if (!user) return null;
  const principal = await loadPrincipal(ctx.sqlite, user.id);
  return principal ? { ...ctx, principal, today } : null;
}
